import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def session(id_, day, converted):
    return {"id": id_, "day": day, "converted": converted}


def test_conversion_rate_none_counts_as_not_converted():
    events = [session("a", 1, True), session("b", 1, None), session("c", 1, False)]
    assert conversion_rate(events) == 1 / 3
    assert conversion_rate([session("a", 1, None)]) == 0.0
    assert conversion_rate([]) == 0.0


def test_pooled_rate_weights_sessions_and_handles_empty_groups():
    groups = {"a": [session("a", 1, True)],
              "b": [session("b", 1, False)] * 3, "empty": []}
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({}) == 0.0
    assert pooled_conversion_rate({"empty": []}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 3), (2, 5), (3, 6), (5, 6)])
def test_conversions_in_window(days, expected):
    assert conversions_in_window([1, 2, 3], days) == expected
    assert conversions_in_window([], days) == 0


def test_parse_log_skips_lines_and_parses_all_flags_and_whitespace():
    lines = ["", "   ", " # a comment, with commas", " x , 2 , 1 ",
             "y, -3, 0", " z , 4 ,   "]
    assert parse_session_log(lines) == [
        session("x", 2, True), session("y", -3, False), session("z", 4, None)
    ]


@pytest.mark.parametrize("bad_line", ["x,1", "x,1,0,extra", "x,nope,1", "x,1,other"])
def test_parse_log_errors_report_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_session_log(["# comment", " ", "ok,1,1", bad_line])


def test_dedupe_keeps_last_duplicate_id_and_sorts_by_day_then_id():
    events = [session("a", 5, True), session("c", 1, True),
              session("b", 1, False), session("a", 1, None),
              session("c", 3, False)]
    assert dedupe_sessions(events) == [events[3], events[2], events[4]]
    assert dedupe_sessions([]) == []


def test_daily_counts_inclusive_with_gaps_outside_and_none():
    events = [session("a", 1, True), session("b", 2, None),
              session("c", 3, True), session("d", 3, True),
              session("e", 4, False), session("f", 5, True)]
    assert daily_conversion_counts(events, 2, 4) == [0, 2, 0]
    assert daily_conversion_counts([], 2, 4) == [0, 0, 0]
    assert daily_conversion_counts(events, 4, 2) == []


def test_campaign_summary_uses_calendar_days_pooled_rate_and_nonempty_groups():
    groups = {"a": [session("a", 1, True)],
              "b": [session("b", 4, False), session("c", 5, True)], "empty": []}
    assert campaign_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert campaign_summary(groups, 0) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert campaign_summary(groups, 10)["recent"] == 2
    assert campaign_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert campaign_summary({}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [session("z", 1, True)], "empty": [],
              "a": [session("a", 1, True)], "b": [session("b", 1, False)]}
    assert top_converting_groups(groups, 2) == ["a", "z"]
    assert top_converting_groups(groups, 10) == ["a", "z", "b"]
    assert top_converting_groups(groups, 0) == []


def test_conversion_rate_by_group_sorted_and_empty_is_none():
    groups = {"z": [], "b": [session("b", 1, None)], "a": [session("a", 1, True)]}
    result = conversion_rate_by_group(groups)
    assert list(result) == ["a", "b", "z"]
    assert result == {"a": 1.0, "b": 0.0, "z": None}


def test_longest_streak_resets_and_only_positive_counts():
    assert longest_conversion_streak([1, 2, 0, 3, -1, 4, 5, 6]) == 3
    assert longest_conversion_streak([0, -1, 0]) == 0
    assert longest_conversion_streak([]) == 0

